import heapq

def match(orders):
    trades = []
    book_buy = []   # heap of (-price, arrival, id)
    book_sell = []  # heap of (price, arrival, id)
    info = {}       # id -> dict(side, price, qty, arrival, active)
    arrival_counter = 0

    def clean_top(heap):
        while heap:
            top_id = heap[0][2]
            rec = info.get(top_id)
            if rec is None or not rec['active']:
                heapq.heappop(heap)
                continue
            break

    def match_incoming(order_id, side, price, qty):
        # price is None for market orders (match at any price)
        nonlocal trades
        if side == 'buy':
            opposite = book_sell
        else:
            opposite = book_buy

        while qty > 0:
            clean_top(opposite)
            if not opposite:
                break
            top = opposite[0]
            resting_id = top[2]
            resting = info[resting_id]
            resting_price = resting['price']

            if price is not None:
                if side == 'buy' and resting_price > price:
                    break
                if side == 'sell' and resting_price < price:
                    break

            trade_qty = min(qty, resting['qty'])
            if side == 'buy':
                trades.append([order_id, resting_id, resting_price, trade_qty])
            else:
                trades.append([resting_id, order_id, resting_price, trade_qty])

            qty -= trade_qty
            resting['qty'] -= trade_qty

            if resting['qty'] == 0:
                resting['active'] = False
                heapq.heappop(opposite)
            # if partially filled, keep at top, but qty of incoming should now be 0 (since trade_qty=min)
            # if incoming qty is 0 now, loop will end
        return qty

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            _, oid = order
            rec = info.get(oid)
            if rec is not None and rec['active'] and rec.get('resting', False):
                rec['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
            remaining = match_incoming(oid, side, price, qty)
            if remaining > 0:
                arrival_counter += 1
                info[oid] = {
                    'side': side,
                    'price': price,
                    'qty': remaining,
                    'arrival': arrival_counter,
                    'active': True,
                    'resting': True
                }
                if side == 'buy':
                    heapq.heappush(book_buy, (-price, arrival_counter, oid))
                else:
                    heapq.heappush(book_sell, (price, arrival_counter, oid))
            else:
                info[oid] = {
                    'side': side,
                    'price': price,
                    'qty': 0,
                    'arrival': None,
                    'active': False,
                    'resting': False
                }

        elif typ == 'ioc':
            _, oid, side, price, qty = order
            remaining = match_incoming(oid, side, price, qty)
            info[oid] = {
                'side': side,
                'price': price,
                'qty': remaining,
                'arrival': None,
                'active': False,
                'resting': False
            }

        elif typ == 'market':
            _, oid, side, qty = order
            remaining = match_incoming(oid, side, None, qty)
            info[oid] = {
                'side': side,
                'price': None,
                'qty': remaining,
                'arrival': None,
                'active': False,
                'resting': False
            }

    return trades

